/**
 * Turn `src/python/*.py` into one generated TypeScript module of string constants. The `.py` files
 * are the source of truth - readable, `ast.parse`-able - but a `.py` beside a `.ts` does not
 * survive `tsc`, and a runtime `fetch("./python/browser_http.py")` would resolve against whatever
 * path a consumer's bundler produced. Embedding them as strings leaves one module graph, no assets,
 * no paths; `--check` fails when the generated file has drifted.
 *
 * `#` comments are removed on the way (see `strip-python-comments.mjs`): they are a quarter of the
 * engine's gzipped bytes and no browser needs them. Lines are kept, so a traceback's line numbers
 * still point into `src/python/*.py`; `tests/python-sources.test.ts` checks the AST is unchanged.
 */
import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { stripPythonComments } from "./strip-python-comments.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const PY_DIR = join(HERE, "..", "src", "python");
const OUT = join(HERE, "..", "src", "worker", "python-sources.generated.ts");

/** `browser_http.py` -> `BROWSER_HTTP_PY`. */
const constName = (file) => `${file.replace(/\.py$/, "").toUpperCase()}_PY`;

function render() {
  const files = readdirSync(PY_DIR)
    .filter((f) => f.endsWith(".py"))
    .sort();
  const parts = [
    "// GENERATED by scripts/gen-python-sources.mjs from src/python/*.py - do not edit.",
    "//",
    "// Run `npm run build` (or the generator directly) after changing a .py file; `npm run",
    "// typecheck` fails if this file has drifted from them.",
    "",
  ];
  const names = [];
  for (const file of files) {
    const source = stripPythonComments(readFileSync(join(PY_DIR, file), "utf8"));
    const name = constName(file);
    names.push([file, name]);
    // JSON.stringify is the encoder, not a template literal: Python is full of backslashes,
    // backticks and `${`, and every one of them is a syntax error or an injection in a template.
    parts.push(`/** src/python/${file}, comments removed, lines kept. */`);
    parts.push(`export const ${name}: string = ${JSON.stringify(source)};`);
    parts.push("");
  }
  parts.push("/** Every helper, keyed by the filename it must be written to in Python's VFS. */");
  parts.push("export const PYTHON_SOURCES: ReadonlyArray<readonly [string, string]> = [");
  for (const [file, name] of names) parts.push(`  ["${file}", ${name}],`);
  parts.push("];");
  parts.push("");
  return parts.join("\n");
}

const next = render();
const check = process.argv.includes("--check");

let current = null;
try {
  current = readFileSync(OUT, "utf8");
} catch {
  /* not generated yet */
}

if (check) {
  if (current !== next) {
    console.error(
      "python-sources.generated.ts is out of date with src/python/*.py.\n" +
        "Run `npm run build -w @freva-org/browser-python` (or node scripts/gen-python-sources.mjs).",
    );
    process.exit(1);
  }
  console.log("python-sources.generated.ts is up to date");
} else if (current !== next) {
  writeFileSync(OUT, next);
  console.log(`python-sources.generated.ts regenerated, ${next.length} bytes`);
} else {
  console.log("python-sources.generated.ts is up to date");
}
